arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>&types=public_channel,private_channel" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR:', d); sys.exit(1)
for c in d['channels']:
    if 'incident' in c['name'].lower() or 'payment' in c['name'].lower() or 'oncall' in c['name'].lower() or 'on-call' in c['name'].lower():
        print(c['name'], c['id'])
"

